export function isDeepSeekFileId(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length <= 255 &&
    /^file-api-[A-Za-z0-9_-]+$/.test(value)
  );
}

export function isVisionModel(model: string): boolean {
