           weatherJobId: result.id,
           weatherJobResult: true,
         },
       ];
       this.notify();
     }
   } catch {
     // The capsule keeps collecting; the next sync asks again.
   } finally {
     this.isSyncingWeatherJobs = false;
   }
 }

