  if (!(file instanceof File)) {
    return jsonError(400, {
      code: 'missing_file',
      message: 'Выберите файл для загрузки.',
    });
  }

  if (classifyAttachment(file) !== 'image') {
    return jsonError(400, {
      code: 'invalid_file',
      message: 'DeepSeek принимает как вложения только JPEG, PNG, GIF и WebP.',
    });
  }

  if (file.size > MAX_IMAGE_ATTACHMENT_BYTES) {
    return jsonError(413, {
      code: 'file_too_large',
      message: 'Изображение слишком большое.',
    });
  }

  const validation = validateAttachmentFiles([file]);
  if (!validation.ok) {
    return jsonError(400, {
      code: 'invalid_file',
      message: validation.message,
    });
  }

  const upstreamForm = new FormData();
  upstreamForm.set('purpose', 'user_data');
  upstreamForm.set('file', file, file.name);

  let upstreamResponse: Response;

  try {
    upstreamResponse = await fetch(DEEPSEEK_FILES_ENDPOINT, {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}` },
      body: upstreamForm,
      cache: 'no-store',
      signal: request.signal,

prepareAttachments(
   files: File[],
   signal: AbortSignal,
 ): Promise<ChatAttachment[]> {
   const validation = validateAttachmentFiles(files);
   if (!validation.ok) throw new Error(validation.message);

   if (
     files.some((file) => classifyAttachment(file) === 'image') &&
     !isVisionModel(this.config.model)
   ) {
     throw new Error(
       'Изображения поддерживаются только моделями DeepSeek Flash. Создайте агента с моделью Flash.',
     );
   }

   return Promise.all(
     files.map(async (file): Promise<ChatAttachment> => {
       const kind = classifyAttachment(file);
       if (!kind)
         throw new Error(`Формат файла «${file.name}» не поддерживается.`);

       if (kind === 'text') {
         const text = await file.text();
         if (signal.aborted) throw new DOMException('Aborted', 'AbortError');
         if (!text.trim() || text.includes('\u0000')) {
           throw new Error(
             `Файл «${file.name}» не содержит читаемого текста.`,
           );
         }

         return {
           id: createId(),
           kind,
           name: file.name,
           mediaType: file.type || 'text/plain',
           size: file.size,
           text,
         };
       }

       const formData = new FormData();
       formData.set('file', file, file.name);
       const response = await fetch('/api/files', {
         method: 'POST',
         body: formData,
         signal,
       });

       if (!response.ok) {
         const payload = (await response
           .json()
           .catch(() => null)) as ChatErrorPayload | null;
         throw new Error(
           payload?.error.message ??
             `Не удалось загрузить файл «${file.name}».`,
         );
       }

       const payload = (await response
         .json()
         .catch(() => null)) as FileUploadResponsePayload | null;
       if (!isDeepSeekFileId(payload?.file.fileId)) {
         throw new Error(`Не удалось загрузить файл «${file.name}».`);
       }

       return {
         id: createId(),
         kind,
         name: file.name,
         mediaType: file.type,
         size: file.size,
         fileId: payload.file.fileId,
       };
     }),
   );
 }

